// Format mode used by field descriptors and bind parameters.
export type Mode = 'text' | 'binary'

// Every supported backend message type.
export type MessageName =
  | 'parseComplete'
  | 'bindComplete'
  | 'closeComplete'
  | 'noData'
  | 'portalSuspended'
  | 'replicationStart'
  | 'emptyQuery'
  | 'copyDone'
  | 'copyData'
  | 'rowDescription'
  | 'parameterDescription'
  | 'parameterStatus'
  | 'backendKeyData'
  | 'notification'
  | 'readyForQuery'
  | 'commandComplete'
  | 'dataRow'
  | 'copyInResponse'
  | 'copyOutResponse'
  | 'authenticationOk'
  | 'authenticationMD5Password'
  | 'authenticationCleartextPassword'
  | 'authenticationSASL'
  | 'authenticationSASLContinue'
  | 'authenticationSASLFinal'
  | 'error'
  | 'notice'

// Common header present on every backend message.
export interface BackendMessage {
  readonly name: MessageName
  readonly length: number
}

// Factory for the small, fixed-size backend messages that carry no payload.
const createBackendMessage = (name: MessageName, length: number): BackendMessage => ({
  name,
  length,
})

export const parseComplete = createBackendMessage('parseComplete', 5)
export const bindComplete = createBackendMessage('bindComplete', 5)
export const closeComplete = createBackendMessage('closeComplete', 5)
export const noData = createBackendMessage('noData', 5)
export const portalSuspended = createBackendMessage('portalSuspended', 5)
export const replicationStart = createBackendMessage('replicationStart', 4)
export const emptyQuery = createBackendMessage('emptyQuery', 4)
export const copyDone = createBackendMessage('copyDone', 4)

// Shared shape of ERROR and NOTICE messages populated by field parsing.
export interface NoticeOrError {
  message: string | undefined
  severity: string | undefined
  code: string | undefined
  detail: string | undefined
  hint: string | undefined
  position: string | undefined
  internalPosition: string | undefined
  internalQuery: string | undefined
  where: string | undefined
  schema: string | undefined
  table: string | undefined
  column: string | undefined
  dataType: string | undefined
  constraint: string | undefined
  file: string | undefined
  line: string | undefined
  routine: string | undefined
}

// Represents an ErrorResponse ('E') message from the backend.
export class DatabaseError extends Error implements NoticeOrError {
  public severity: string | undefined
  public code: string | undefined
  public detail: string | undefined
  public hint: string | undefined
  public position: string | undefined
  public internalPosition: string | undefined
  public internalQuery: string | undefined
  public where: string | undefined
  public schema: string | undefined
  public table: string | undefined
  public column: string | undefined
  public dataType: string | undefined
  public constraint: string | undefined
  public file: string | undefined
  public line: string | undefined
  public routine: string | undefined

  constructor(
    message: string,
    public readonly length: number,
    public readonly name: MessageName
  ) {
    super(message)
    Object.setPrototypeOf(this, new.target.prototype)
  }
}

// A single CopyData ('d') chunk received during COPY ... TO/FRONTEND.
export class CopyDataMessage {
  public readonly name = 'copyData'

  constructor(
    public readonly length: number,
    public readonly chunk: Buffer
  ) {}
}

// Base class for CopyInResponse ('G') and CopyOutResponse ('H').
export class CopyResponse {
  public readonly columnTypes: number[]

  constructor(
    public readonly length: number,
    public readonly name: MessageName,
    public readonly binary: boolean,
    columnCount: number
  ) {
    this.columnTypes = new Array(columnCount)
  }
}

// Field metadata returned in a RowDescription ('T') message.
export class Field {
  constructor(
    public readonly name: string,
    public readonly tableID: number,
    public readonly columnID: number,
    public readonly dataTypeID: number,
    public readonly dataTypeSize: number,
    public readonly dataTypeModifier: number,
    public readonly format: Mode
  ) {}
}

// RowDescription ('T') message describing the columns in a result set.
export class RowDescriptionMessage {
  public readonly name: MessageName = 'rowDescription'
  public readonly fields: Field[]

  constructor(
    public readonly length: number,
    public readonly fieldCount: number
  ) {
    this.fields = new Array(fieldCount)
  }
}

// ParameterDescription ('t') message describing statement parameter types.
export class ParameterDescriptionMessage {
  public readonly name: MessageName = 'parameterDescription'
  public readonly dataTypeIDs: number[]

  constructor(
    public readonly length: number,
    public readonly parameterCount: number
  ) {
    this.dataTypeIDs = new Array(parameterCount)
  }
}

// ParameterStatus ('S') message reporting a runtime-configurable server variable.
export class ParameterStatusMessage {
  public readonly name: MessageName = 'parameterStatus'

  constructor(
    public readonly length: number,
    public readonly parameterName: string,
    public readonly parameterValue: string
  ) {}
}

// AuthenticationMD5Password ('R') message carrying the 4-byte salt.
export class AuthenticationMD5Password implements BackendMessage {
  public readonly name: MessageName = 'authenticationMD5Password'

  constructor(
    public readonly length: number,
    public readonly salt: Buffer
  ) {}
}

// BackendKeyData ('K') message providing cancellation identifiers.
export class BackendKeyDataMessage {
  public readonly name: MessageName = 'backendKeyData'

  constructor(
    public readonly length: number,
    public readonly processID: number,
    public readonly secretKey: number
  ) {}
}

// NotificationResponse ('A') message from LISTEN/NOTIFY.
export class NotificationResponseMessage {
  public readonly name: MessageName = 'notification'

  constructor(
    public readonly length: number,
    public readonly processId: number,
    public readonly channel: string,
    public readonly payload: string
  ) {}
}

// ReadyForQuery ('Z') message indicating the backend is ready for a new query.
export class ReadyForQueryMessage {
  public readonly name: MessageName = 'readyForQuery'

  constructor(
    public readonly length: number,
    public readonly status: string
  ) {}
}

// CommandComplete ('C') message containing the command status tag.
export class CommandCompleteMessage {
  public readonly name: MessageName = 'commandComplete'

  constructor(
    public readonly length: number,
    public readonly text: string
  ) {}
}

// DataRow ('D') message carrying one result row as an array of raw field values.
export class DataRowMessage {
  public readonly name: MessageName = 'dataRow'
  public readonly fieldCount: number

  constructor(
    public readonly length: number,
    public readonly fields: any[]
  ) {
    this.fieldCount = fields.length
  }
}

// NoticeResponse ('N') message; structurally identical to an error but not fatal.
export class NoticeMessage implements BackendMessage, NoticeOrError {
  public readonly name = 'notice'
  public severity: string | undefined
  public code: string | undefined
  public detail: string | undefined
  public hint: string | undefined
  public position: string | undefined
  public internalPosition: string | undefined
  public internalQuery: string | undefined
  public where: string | undefined
  public schema: string | undefined
  public table: string | undefined
  public column: string | undefined
  public dataType: string | undefined
  public constraint: string | undefined
  public file: string | undefined
  public line: string | undefined
  public routine: string | undefined

  constructor(
    public readonly length: number,
    public readonly message: string | undefined
  ) {}
}